1	{ config, lib, pkgs, ... }:
2	
3	let
4	  opencodeConfig = {
5	    "$schema" = "https://opencode.ai/config.json";
6	    # opencode-claude-memory reads/writes Claude Code's own memory store
7	    # (~/.claude/projects/<sanitized canonical git root>/memory/), so both CLIs
8	    # share one set of memories. Pinned because it injects a system prompt and
9	    # runs a per-turn recall subagent. That subagent is pinned via
10	    # OPENCODE_MEMORY_RECALL_MODEL in the wrapper below — to the cheapest Coding
11	    # Plan model rather than the session's, since recall fires every turn.
12	    # Set OPENCODE_MEMORY_IGNORE=1 to disable injection.
13	    plugin = [ "opencode-model-stats@0.2.3" "opencode-claude-memory@1.7.3" ];
14	    disabled_providers = [ "opencode" "zai" ];
15	    # Pin the default: unset, opencode picks one, and non-interactive launches
16	    # (drovr's review panel) inherit whatever that is.
17	    #
18	    # Z.ai's hosted GLM rather than the local model. lemonade serves 4 slots off
19	    # one GPU, and with hakobiya on the same router a turn queues behind
20	    # multi-minute triage requests -- a one-token reply measured 3m14s, and
21	    # decode falls to 2-4 t/s under load against 31 t/s idle. ko-ag is still
22	    # registered below, so `/models` can still reach the local box on purpose.
23	    model = "zai-coding-plan/glm-5.3";
24	    # Title generation and other throwaway calls. Unset, these inherit `model`
25	    # above and bill the flagship for a six-word title.
26	    small_model = "zai-coding-plan/glm-5.3-flash";
27	    provider = {
28	      mcloud = {
29	        npm = "@ai-sdk/openai-compatible";
30	        name = "Modular (internal)";
31	        # baseURL injected at activation from the sops secret
32	        # ~/.config/opencode/mcloud-base-url so the private hostname never
33	        # appears in the committed config.
34	        options = { };
35	        models = {
36	          "MiniMaxAI/MiniMax-M3" = { name = "MiniMax M3"; };
37	        };
38	      };
39	      "ko-ag" = {
40	        npm = "@ai-sdk/openai-compatible";
41	        name = "ko.ag";
42	        options = {
43	          # LAN address of the in-cluster litellm router (Cilium LoadBalancer,
44	          # L2-announced). ai.ko.ag is GONE: it fronted this same router through
45	          # a Workers façade and CF AI Gateway, and 524'd structurally because
46	          # litellm emits no bytes until its upstream produces a first token,
47	          # which Cloudflare reads as a dead origin. See the kube repo's
48	          # docs/litellm-access.md.
49	          #
50	          # Plain HTTP, and the API key crosses the LAN in cleartext. Acceptable
51	          # here because the only paths to this address are the home LAN and the
52	          # 10.9.0.0/24 WireGuard VPN, and the key authorizes inference on a
53	          # self-hosted model. Fixing it means a TLS sidecar on the Service, not
54	          # a change on this side.
55	          baseURL = "http://10.0.7.240:4000/v1";
56	        };
57	        # `glm` is litellm's own model-group name, not a lemonade id: it routes
58	        # lemonade -> Z.ai Coding Plan -> OpenRouter, so a dead local model
59	        # fails over instead of erroring. The old lowercase lemonade id still
60	        # works via model_group_alias, but that alias exists to be retired.
61	        models = {
62	          "glm" = { name = "GLM (lemonade -> Z.ai -> OpenRouter)"; };
63	        };
64	      };
65	      # Built-in models.dev providers; apiKey injected at activation from sops.
66	      "zai-coding-plan" = {
67	        npm = "@ai-sdk/openai-compatible";
68	        name = "Z.AI Coding Plan";
69	        options = {
70	          baseURL = "https://api.z.ai/api/coding/paas/v4";
71	        };
72	      };
73	    };
74	  };
75	  configTemplate = pkgs.writeText "opencode.json.tmpl" (builtins.toJSON opencodeConfig);
76	
77	  # opencode-model-stats adds `session_id`/`message_id` headers alongside the
78	  # canonical `x-opencode-*` forms. Modular's edge proxy (Envoy) 400s any
79	  # request with an underscore-named header before it reaches the model server.
80	  # Strip those two lines from the cached plugin source — the x- prefixed
81	  # headers carry the same data.
82	  patchModelStats = pkgs.writeShellScript "opencode-patch-model-stats" ''
83	    set -eu
84	    shopt -s nullglob
85	    for f in "$HOME"/.cache/opencode/packages/opencode-model-stats@*/node_modules/opencode-model-stats/src/server.ts; do
86	      if ${pkgs.gnugrep}/bin/grep -q '\["session_id"\]\|\["message_id"\]' "$f"; then
87	        ${pkgs.gnused}/bin/sed -i \
88	          -e '/output\.headers\["session_id"\] *= *ctx\.sessionID/d' \
89	          -e '/output\.headers\["message_id"\] *= *ctx\.messageID/d' \
90	          "$f"
91	      fi
92	    done
93	  '';
94	in
95	{
96	  nixpkgs.overlays = [
97	    (final: prev: {
98	      opencode = prev.symlinkJoin {
99	        name = "opencode-${prev.opencode.version or "wrapped"}-mcloudpatch";
100	        paths = [ prev.opencode ];
101	        nativeBuildInputs = [ prev.makeWrapper ];
102	        postBuild = ''
103	          rm -f $out/bin/opencode
104	          makeWrapper ${prev.opencode}/bin/opencode $out/bin/opencode \
105	            --run ${patchModelStats} \
106	            --set-default OPENCODE_MEMORY_RECALL_MODEL zai-coding-plan/glm-5.3-flash
107	        '';
108	      };
109	    })
110	  ];
111	
112	  # opencode.json is rendered at activation by injecting the sops-decrypted
113	  # Modular API key into provider.mcloud.options.apiKey. Not symlinked into the
114	  # nix store so the secret never leaks to world-readable /nix/store paths.
115	  home.activation.opencodeConfig = lib.hm.dag.entryAfter [ "writeBoundary" "sops-nix" ] ''
116	    DEST="$HOME/.config/opencode/opencode.json"
117	    TMPL="${configTemplate}"
118	    MCLOUD_KEY_FILE="$HOME/.config/local-auto-mode/api-key"
119	    MCLOUD_URL_FILE="$HOME/.config/opencode/mcloud-base-url"
120	    KOAG_KEY_FILE="$HOME/.config/opencode/ko-ag-key"
121	    ZAI_KEY_FILE="$HOME/.config/opencode/zai-key"
122	    $DRY_RUN_CMD mkdir -p "$HOME/.config/opencode"
123	    JQ_ARGS=()
124	    JQ_FILTER='.'
125	    if [ -r "$MCLOUD_KEY_FILE" ]; then
126	      JQ_ARGS+=(--rawfile mcloudKey "$MCLOUD_KEY_FILE")
127	      JQ_FILTER="$JQ_FILTER | .provider.mcloud.options.apiKey = (\$mcloudKey | sub(\"\\n$\"; \"\"))"
128	    fi
129	    if [ -r "$MCLOUD_URL_FILE" ]; then
130	      JQ_ARGS+=(--rawfile mcloudUrl "$MCLOUD_URL_FILE")
131	      JQ_FILTER="$JQ_FILTER | .provider.mcloud.options.baseURL = (\$mcloudUrl | sub(\"\\n$\"; \"\"))"
132	    fi
133	    if [ -r "$KOAG_KEY_FILE" ]; then
134	      JQ_ARGS+=(--rawfile koagKey "$KOAG_KEY_FILE")
135	      JQ_FILTER="$JQ_FILTER | .provider.\"ko-ag\".options.apiKey = (\$koagKey | sub(\"\\n$\"; \"\"))"
136	    fi
137	    if [ -e "$ZAI_KEY_FILE" ]; then
138	      JQ_ARGS+=(--rawfile zaiKey "$ZAI_KEY_FILE")
139	      JQ_FILTER="$JQ_FILTER | .provider.\"zai-coding-plan\".options.apiKey = (\$zaiKey | sub(\"\\n$\"; \"\"))"
140	    fi
141	    if [ ''${#JQ_ARGS[@]} -gt 0 ]; then
142	      $DRY_RUN_CMD ${pkgs.jq}/bin/jq "''${JQ_ARGS[@]}" "$JQ_FILTER" "$TMPL" > "$DEST.new"
143	      $DRY_RUN_CMD mv "$DEST.new" "$DEST"
144	      $DRY_RUN_CMD chmod 0600 "$DEST"
145	    else
146	      $DRY_RUN_CMD cp "$TMPL" "$DEST"
147	      $DRY_RUN_CMD chmod 0644 "$DEST"
148	    fi
149	  '';
150	
151	  # C-g is Emacs's universal cancel; map it to session_interrupt and unbind it
152	  # from messages_first (which used "ctrl+g,home"). C-f/C-b mirror
153	  # forward-char/backward-char in confirmation dialogs (select next/prev).
154	  xdg.configFile."opencode/tui.json".text = builtins.toJSON {
155	    "$schema" = "https://opencode.ai/tui.json";
156	    keybinds = {
157	      session_interrupt = "escape,ctrl+g";
158	      messages_first = "home";
159	      "dialog.select.next" = "down,ctrl+n,ctrl+f";
160	      "dialog.select.prev" = "up,ctrl+p,ctrl+b";
161	    };
162	  };
163	
164	  # herdr integration: file-based opencode plugin reporting lifecycle state and
165	  # session identity to the local herdr socket while opencode runs in a herdr
166	  # pane. Auto-loaded from ~/.config/opencode/plugins/ (no entry in
167	  # opencode.json's `plugin` array, which is for npm plugins). No-op unless
168	  # HERDR_ENV=1. Vendored verbatim from `herdr integration install opencode`
169	  # (v8); regenerate if `herdr integration status` reports it outdated.
170	  xdg.configFile."opencode/plugins/herdr-agent-state.js".source =
171	    ./home/opencode/plugins/herdr-agent-state.js;
172	
173	  # Belt-and-suspenders: 0.2.4 reintroduced legacy session_id/message_id headers
174	  # that Modular's Envoy rejects with 400. Patch any cached copy after activation.
175	  home.activation.patchOpencodeModelStats = lib.hm.dag.entryAfter [ "opencodeConfig" ] ''
176	    $DRY_RUN_CMD ${patchModelStats}
177	  '';
178	}
